from __future__ import annotations

from dataclasses import dataclass

from rasa.builder import config as builder_config


@dataclass(frozen=True)
class PydanticAIConfig:
    """Runtime settings for Copilot v2."""

    model_name: str = "openai-chat:gpt-5.4"
    max_model_requests: int = 50
    mcp_protocol: str = builder_config.MCP_SERVER_PROTOCOL
    mcp_host: str = builder_config.MCP_SERVER_HOST
    mcp_port: int = builder_config.MCP_SERVER_PORT
    mcp_path: str = "/mcp"

    @property
    def mcp_url(self) -> str:
        """Return the MCP streamable-HTTP endpoint URL.

        The scheme is driven by ``MCP_SERVER_PROTOCOL`` (default ``http``).
        The MCP server is a co-located loopback service, so ``http`` is the
        expected default; override to ``https`` via env when the server is
        fronted with TLS.
        """
        return f"{self.mcp_protocol}://{self.mcp_host}:{self.mcp_port}{self.mcp_path}"
